PROC SQL;
	create table ep9 as
	select A.*, B.insiders_perc_10yr, B.internal_10yr, B.external_10yr, C.state, D.state as state_full, E.score as nca_score
	from ep8 as A LEFT JOIN inside_ceo0 as B
	on A.ffi48=B.ffi48 and year(A.date_of_request)=B.year+1
